def combination_sum(cands, target):
    res = []
    def bt(i, rem, path):
        if rem == 0:
            res.append(path[:]); return
        if rem < 0: return
        for j in range(i, len(cands)):
            path.append(cands[j])
            bt(j, rem - cands[j], path)
            path.pop()
    bt(0, target, [])
    return res

def total_n_queens(n):
    cols, d1, d2 = set(), set(), set()
    def bt(r):
        if r == n: return 1
        cnt = 0
        for c in range(n):
            if c in cols or (r+c) in d1 or (r-c) in d2: continue
            cols.add(c); d1.add(r+c); d2.add(r-c)
            cnt += bt(r+1)
            cols.remove(c); d1.remove(r+c); d2.remove(r-c)
        return cnt
    return bt(0)

def total_n_queens(n):
    cols = [0]*n; cnt = 0
    def ok(r, c):
        for i in range(r):
            if cols[i] == c or abs(cols[i]-c) == r-i: return False
        return True
    def bt(r):
        nonlocal cnt
        if r == n: cnt += 1; return
        for c in range(n):
            if ok(r, c):
                cols[r] = c
                bt(r+1)
    bt(0)
    return cnt

def generate_parenthesis(n):
    res = []
    def bt(o, c, s):
        if o == n and c == n:
            res.append(s); return
        if o < n: bt(o+1, c, s+'(')
        if c < o: bt(o, c+1, s+')')
    bt(0, 0, '')
    return res

def exist(board, word):
    m, n = len(board), len(board[0])
    def dfs(i, j, k):
        if k == len(word): return True
        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != word[k]: return False
        ch = board[i][j]; board[i][j] = '#'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            if dfs(i+di, j+dj, k+1): return True
        board[i][j] = ch
        return False
    for i in range(m):
        for j in range(n):
            if dfs(i, j, 0): return True
    return False
